import re
import datetime
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


def od_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()


order_id = params["order_id"]
decision = od_text(params.get("decision")) or "release"
reviewed_by = od_text(params.get("reviewed_by"))
found = api.records.get(type_slug="od_orders", record_id=order_id) or {}
order: dict[str, Any] = dict(found.get("record") or {})
stage = od_text(order.get("stage"))
order_number = od_text(order.get("title"))
released = False
handover: dict[str, Any] = {}
if decision == "reject":
    if stage != "rejected":
        api.records.change_stage(type_slug="od_orders", record_id=order_id, stage="rejected", note=od_text(params.get("note"))[:2000] or "Rejected in review")
    result = "rejected"
else:
    d = od_data(order)
    lines = []
    for row in od_order_lines(order_id, order_number):
        line = od_data(row)
        if not od_text(line.get("item_code")):
            continue
        lines.append({"line_number": line.get("line_number"), "item_code": od_text(line.get("item_code")), "quantity": line.get("quantity"), "unit": od_text(line.get("unit")), "note": od_text(line.get("line_note"))})
    handover = {
        "order_number": order_number,
        "account_code": od_text(d.get("account_code")),
        "po_number": od_text(d.get("po_number")),
        "delivery_date": od_text(d.get("delivery_date")),
        "delivery_address": od_text(d.get("delivery_address_raw")),
        "lines": lines,
    }
    if stage != "released":
        patch: dict[str, Any] = {"released_on": od_now()}
        if re.fullmatch(r"[0-9a-fA-F-]{36}", reviewed_by):
            patch["reviewed_by"] = reviewed_by
        api.records.update(type_slug="od_orders", record_id=order_id, record={"data": patch})
        if stage != "confirmed":
            api.records.change_stage(type_slug="od_orders", record_id=order_id, stage="confirmed")
        api.records.change_stage(type_slug="od_orders", record_id=order_id, stage="released", note="Released to the warehouse")
    released = True
    result = "released"
